import pypdf

reader = pypdf.PdfReader('/tmp/downloads/0cc193c893b97f97.pdf')
print("Total pages:", len(reader.pages))

# Search for pages containing state/UT wise unemployment rate (UR) for age 15 and above
matches = []
for i, page in enumerate(reader.pages):
    text = page.extract_text()
    if 'Unemployment Rate' in text or 'unemployment rate' in text or 'UR' in text:
        if 'State' in text or 'state' in text or 'State/UT' in text:
            if '15 years and above' in text or 'age 15' in text or '15 & above' in text:
                matches.append((i+1, text[:200]))

print(f"Found {len(matches)} matching pages:")
for page_num, snippet in matches[:20]:
    print(f"Page {page_num}: {snippet.replace(chr(10), ' ')}")

import pypdf

reader = pypdf.PdfReader('/tmp/downloads/0cc193c893b97f97.pdf')

# Search Appendix A contents pages (61 to 65) for Table number for Unemployment Rate by State/UT
for p in range(60, 66):
    text = reader.pages[p-1].extract_text()
    for line in text.split('\n'):
        if 'Unemployment Rate' in line or 'UR' in line:
            print(f"Page {p}: {line}")

import pypdf

reader = pypdf.PdfReader('/tmp/downloads/0cc193c893b97f97.pdf')

# Let's find where Table (18) is located.
# We can search pages for "Table (18):" or "Table 18"
for p in range(65, 300):
    text = reader.pages[p-1].extract_text()
    if 'Table (18)' in text or 'Table 18' in text:
        if 'Unemployment Rate' in text:
            print(f"Page {p}: {text[:300].replace(chr(10), ' ')}")
